diff --git a/UI Framework/Computed.cs b/UI Framework/Computed.cs
index 21b8fc5..336c8d1 100644
--- a/UI Framework/Computed.cs	
+++ b/UI Framework/Computed.cs	
@@ -94,8 +94,10 @@ public sealed class Computed<T> : IState
             List<IState> added = [];
             try
             {
-                foreach (var dependency in next.Except(dependencies))
+                // Reuse set membership instead of building temporary difference sets.
+                foreach (var dependency in next)
                 {
+                    if (dependencies.Contains(dependency)) continue;
                     dependency.Changed += OnDependencyChanged;
                     added.Add(dependency);
                 }
@@ -105,7 +107,8 @@ public sealed class Computed<T> : IState
                 foreach (var dependency in added) dependency.Changed -= OnDependencyChanged;
                 throw;
             }
-            foreach (var dependency in dependencies.Except(next)) dependency.Changed -= OnDependencyChanged;
+            foreach (var dependency in dependencies)
+                if (!next.Contains(dependency)) dependency.Changed -= OnDependencyChanged;
             dependencies = next;
         }
         return result;
